def solve(inputs: dict) -> float:
    """
    Compute the numerator of a continued fraction
    using the recurrence: p_n = a_n * p_{n-1} + p_{n-2}
    Starting with p_{-1} = 1, p_0 = a_0
    """
    terms = inputs['TERMS']

    if len(terms) == 0:
        return 0.0

    # Initialize
    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0

    if len(terms) == 1:
        return float(p_prev1)

    # Apply recurrence for remaining terms
    for i in range(1, len(terms)):
        a = terms[i]
        p_curr = a * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

scripts.floor_division_sum:
def solve(inputs: dict) -> float:
    """
    Compute sum of floor(A_i / B_i) for all positions i
    """
    a = inputs['A']
    b = inputs['B']

    total = 0
    for i in range(len(a)):
        total += a[i] // b[i]

    return float(total)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    """
    Count the number of inversions in a sequence.
    An inversion is a pair (i, j) where i < j but values[i] > values[j]
    """
    values = inputs['VALUES']

    count = 0
    n = len(values)

    # Check all pairs (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1

    return float(count)

